import { SpotlightRoot } from "@/components/bevelui/spotlight";
import { IconUser, IconFolder, IconFileText } from "@tabler/icons-react";

export default function Layout({ children }) {
  return (
    <SpotlightRoot
      config={{
        categories: [
          { id: "people",   label: "People",   icon: IconUser     },
          { id: "projects", label: "Projects", icon: IconFolder   },
          { id: "docs",     label: "Docs",     icon: IconFileText },
        ],
        hotkey:      "/",
        placeholder: "Search people, projects, docs…",
        storageKey:  `spotlight-${user.id}`,
      }}
      onSearch={async (query, signal) => {
        const [people, projects] = await Promise.all([
          searchPeople(query, signal),
          searchProjects(query, signal),
        ]);
        return [
          ...people.map(p => ({
            id:       p.id,
            title:    p.name,
            subtitle: p.email,
            category: "people",
            icon:     p.avatar,
            href:     `/people/${p.id}`,
          })),
          ...projects.map(p => ({
            id:       p.id,
            title:    p.name,
            subtitle: p.description,
            category: "projects",
            badge:    p.status,
            href:     `/projects/${p.id}`,
          })),
        ];
      }}
    >
      {children}
    </SpotlightRoot>
  );
}

// To clear history programmatically
function ClearHistory() {
  const { clearHistory } = useSpotlight();
  return <button onClick={clearHistory}>Clear search history</button>;
}

import { useSpotlight } from "@/components/bevelui/spotlight";

function SearchButton() {
  const { open, isOpen } = useSpotlight();
  return (
    <button onClick={open}>
      Search <kbd>/</kbd>
    </button>
  );
}
